import{_ as e,o as r,c as t,a2 as l}from"./chunks/framework.XWkMPaqj.js";const d=JSON.parse('{"title":"数据集目录","description":"","frontmatter":{"title":"数据集目录","order":9},"headers":[],"relativePath":"data/datasets.md","filePath":"data/datasets.md"}'),i={name:"data/datasets.md"};function n(o,a,h,s,m,b){return r(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="数据集目录" tabindex="-1">数据集目录 <a class="header-anchor" href="#数据集目录" aria-label="Permalink to &quot;数据集目录&quot;">​</a></h1><h2 id="多基因组比对与泛基因组数据集" tabindex="-1">多基因组比对与泛基因组数据集 <a class="header-anchor" href="#多基因组比对与泛基因组数据集" aria-label="Permalink to &quot;多基因组比对与泛基因组数据集&quot;">​</a></h2><h3 id="mga-dataset" tabindex="-1">MGA-Dataset <a class="header-anchor" href="#mga-dataset" aria-label="Permalink to &quot;MGA-Dataset&quot;">​</a></h3><ul><li><a href="https://github.com/malabz/MGA-Dataset" target="_blank" rel="noreferrer">MGA-Dataset</a> 是课题组持续维护的多基因组比对（MGA）与泛基因组（Pangenome）数据资源导航库，汇总数据集说明、官方来源和下载入口，不直接存放数据文件。</li><li>该资源按真实数据与模拟数据分类，当前覆盖人类、植物、真菌、跨类群基因组集合以及模拟基准集，并标注 T2T、Chromosome、Scaffold、Contig 等组装级别，便于根据研究对象和评测需求选择数据。</li></ul><h2 id="dna-rna真实数据集" tabindex="-1">DNA/RNA真实数据集 <a class="header-anchor" href="#dna-rna真实数据集" aria-label="Permalink to &quot;DNA/RNA真实数据集&quot;">​</a></h2><h3 id="ancient-human-partial-mitochondrial-dna" tabindex="-1">Ancient human partial mitochondrial DNA <a class="header-anchor" href="#ancient-human-partial-mitochondrial-dna" aria-label="Permalink to &quot;Ancient human partial mitochondrial DNA&quot;">​</a></h3><ul><li>古代人类线粒体高可变区I和高可变区II的基因序列，长度350bp左右，293条高可变区I，100条高可变区II，数据集混在一起，比对时需要分开使用</li><li>Ref: Ancient DNA Reveals Key Stages in the Formation of Central European Mitochondrial Genetic Diversity. DOI: 10.1126/science.1241844</li><li>下载 (zipped file): <a href="http://lab.malab.cn/soft/WMSA2/data/mt.zip" target="_blank" rel="noreferrer">mt.zip</a></li></ul><h3 id="mitochondrial-genomes" tabindex="-1">mitochondrial genomes <a class="header-anchor" href="#mitochondrial-genomes" aria-label="Permalink to &quot;mitochondrial genomes&quot;">​</a></h3><ul><li>人类线粒体基因组，672条高度相似的DNA序列，最大长度16579bp</li><li>Ref: Tanaka M., et al. (2004) Mitochondrial genome variation in eastern Asia and the peopling of Japan. Genome Res,14(10a), 1832-1850.</li><li>Download: <a href="http://lab.malab.cn/soft/halign/data/mt1x.zip" target="_blank" rel="noreferrer">1x</a> (219KB) <a href="http://lab.malab.cn/soft/halign/data/mt20x.zip" target="_blank" rel="noreferrer">20x</a> (4.27MB) <a href="http://lab.malab.cn/soft/halign/data/mt50x.zip" target="_blank" rel="noreferrer">50x</a> (10.666MB) <a href="http://lab.malab.cn/soft/halign/data/mt100x.zip" target="_blank" rel="noreferrer">100x</a> (21.325MB)</li></ul><h3 id="human-genome" tabindex="-1">Human Genome <a class="header-anchor" href="#human-genome" aria-label="Permalink to &quot;Human Genome&quot;">​</a></h3><h4 id="人类基因组基因" tabindex="-1">人类基因组基因 <a class="header-anchor" href="#人类基因组基因" aria-label="Permalink to &quot;人类基因组基因&quot;">​</a></h4><ul><li>含有21个人的完整基因,因数据量过大，仅提供基因组的<a href="http://lab.malab.cn/~cjt/MSA/data/Human_Genome_21.html" target="_blank" rel="noreferrer">下载链接</a>。</li><li>注意：CHM13_T2T_v1.1 已经更新为 CHM13_T2T_v2.0，请使用 <a href="https://s3-us-west-2.amazonaws.com/human-pangenomics/T2T/CHM13/assemblies/analysis_set/chm13v2.0.fa.gz" target="_blank" rel="noreferrer">这个链接</a> 获取。</li></ul><h4 id="人类y染色体基因组" tabindex="-1">人类Y染色体基因组 <a class="header-anchor" href="#人类y染色体基因组" aria-label="Permalink to &quot;人类Y染色体基因组&quot;">​</a></h4><ul><li>共44条，均由多个片段拼接而成（参考序列见 CHM13_T2T_\\v2.0）</li><li>Download: <a href="ftp://ftp.1000genomes.ebi.ac.uk/vol1/ftp/data_collections/HGSVC3/working/20230412_sigY_assembly_data/assemblies/verkko_1.0_release/chrY/" target="_blank" rel="noreferrer">Link</a></li><li>Ref1: Hallast, Pille, et al. &quot;Assembly of 43 human Y chromosomes reveals extensive complexity and variation.&quot; Nature (2023): 1-10.</li><li>Ref2: Rhie, Arang, et al. &quot;The complete sequence of a human Y chromosome.&quot; Nature (2023): 1-11.</li></ul><h4 id="_3条人类1号染色体" tabindex="-1">3条人类1号染色体 <a class="header-anchor" href="#_3条人类1号染色体" aria-label="Permalink to &quot;3条人类1号染色体&quot;">​</a></h4><ul><li>由于数据过大，采用了分卷压缩.</li><li>Download: <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.001" target="_blank" rel="noreferrer">part 1</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.002" target="_blank" rel="noreferrer">part 2</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.003" target="_blank" rel="noreferrer">part 3</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.004" target="_blank" rel="noreferrer">part 4</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.005" target="_blank" rel="noreferrer">part 5</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.006" target="_blank" rel="noreferrer">part 6</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.007" target="_blank" rel="noreferrer">part 7</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.008" target="_blank" rel="noreferrer">part 8</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/3-Human-chromosome-1.zip.009" target="_blank" rel="noreferrer">part 9</a></li></ul><h3 id="_16s-rrna" tabindex="-1">16S rRNA <a class="header-anchor" href="#_16s-rrna" aria-label="Permalink to &quot;16S rRNA&quot;">​</a></h3><ul><li>16S rRNA基因是细菌上编码rRNA相对应的DNA序列，相似度不高，最大长度1586bp</li><li>Ref: DeSantis, T. Z., et al.(2006) NAST: a multiple sequence alignment server for comparative analysis of 16S rRNA genes. Nucleic Acids Res, 34, W394-399.</li><li>Download: <a href="http://lab.malab.cn/soft/halign/data/16ssmall.zip" target="_blank" rel="noreferrer">small</a> (21.864MB) <a href="http://lab.malab.cn/soft/halign/data/16sbig.zip" target="_blank" rel="noreferrer">big</a> (197.224MB)</li></ul><h3 id="mycobacterium-23s-rrna-sequences" tabindex="-1">Mycobacterium 23S rRNA sequences <a class="header-anchor" href="#mycobacterium-23s-rrna-sequences" aria-label="Permalink to &quot;Mycobacterium 23S rRNA sequences&quot;">​</a></h3><ul><li>641 Mycobacterium 23S rRNA sequences with lengths ranging from 1909 to 3485 bp were downloaded as another dataset from the <a href="http://www.arb-silva.de/" target="_blank" rel="noreferrer">SILVA rRNA database</a> of Bacteria, Archaea and Eukarya.</li><li>Download: <a href="http://lab.malab.cn/%7Etfr/HAlign3_testdata/23s_rRNA.tar.xz" target="_blank" rel="noreferrer">23s_rRNA.tar.xz</a></li></ul><h3 id="neisseria-meningitidis" tabindex="-1">Neisseria-meningitidis <a class="header-anchor" href="#neisseria-meningitidis" aria-label="Permalink to &quot;Neisseria-meningitidis&quot;">​</a></h3><ul><li>5 条序列，长度为 2,190,088，fasta 格式</li><li>Download: <a href="https://github.com/malabz/Halign-G/raw/main/data/Neisseria-meningitidis.zip" target="_blank" rel="noreferrer">link</a></li></ul><h3 id="streptococcus-pneumoniae" tabindex="-1">Streptococcus-pneumoniae <a class="header-anchor" href="#streptococcus-pneumoniae" aria-label="Permalink to &quot;Streptococcus-pneumoniae&quot;">​</a></h3><ul><li>11 条序列，长度 2,138,975~2,139,054，fasta 格式</li><li>Download: <a href="https://github.com/malabz/Halign-G/raw/main/data/Streptococcus-pneumoniae.zip" target="_blank" rel="noreferrer">link</a></li></ul><h3 id="escherichia-coil" tabindex="-1">Escherichia-coil <a class="header-anchor" href="#escherichia-coil" aria-label="Permalink to &quot;Escherichia-coil&quot;">​</a></h3><ul><li>30 条序列，长度 5,060,511~5,060,749，fasta 格式。由于数据过大，采用了分卷压缩</li><li>Download: <a href="https://github.com/malabz/Halign-G/raw/main/data/Escherichia-coil.zip.001" target="_blank" rel="noreferrer">part 1</a>, <a href="https://github.com/malabz/Halign-G/raw/main/data/Escherichia-coil.zip.002" target="_blank" rel="noreferrer">part 2</a></li></ul><h3 id="gmgc-数据集" tabindex="-1">GMGC 数据集 <a class="header-anchor" href="#gmgc-数据集" aria-label="Permalink to &quot;GMGC 数据集&quot;">​</a></h3><ul><li>Global Microbial Gene Catalog 数据集，fasta 格式。</li><li><a href="https://gmgc.embl.de/download.cgi" target="_blank" rel="noreferrer">原始数据下载</a></li><li><a href="https://github.com/malabz/GMGC-data" target="_blank" rel="noreferrer">按照长度进行分组存储</a></li><li>Ref: Coelho, L.P., et al. Towards the biogeography of prokaryotic genes. Nature 601, 252–256 (2022).</li></ul><h3 id="hiv-数据集" tabindex="-1">HIV 数据集 <a class="header-anchor" href="#hiv-数据集" aria-label="Permalink to &quot;HIV 数据集&quot;">​</a></h3><ul><li>截至 2021 年的 HIV 数据集，fasta 格式。</li><li><a href="https://www.hiv.lanl.gov/content/sequence/NEWALIGN/align.html" target="_blank" rel="noreferrer">原始数据下载</a></li><li><a href="https://github.com/malabz/HIV-data" target="_blank" rel="noreferrer">按照长度进行分组存储</a></li><li>Ref: <a href="https://www.hiv.lanl.gov/" target="_blank" rel="noreferrer">https://www.hiv.lanl.gov/</a> <a href="https://www.hiv.lanl.gov/content/sequence/HIV/refer.html" target="_blank" rel="noreferrer">参考如何引用 HIV 数据集</a></li></ul><h2 id="病毒基因组数据集" tabindex="-1">病毒基因组数据集 <a class="header-anchor" href="#病毒基因组数据集" aria-label="Permalink to &quot;病毒基因组数据集&quot;">​</a></h2><h3 id="covid-19" tabindex="-1">COVID-19 <a class="header-anchor" href="#covid-19" aria-label="Permalink to &quot;COVID-19&quot;">​</a></h3><ul><li>新冠病毒基因序列，总共156条，相似度较高，长度大于29000bp</li><li><a href="http://lab.malab.cn/~zsl/Periodical_results/data/2019nCoVR_20200301.zip" target="_blank" rel="noreferrer">http://lab.malab.cn/~zsl/Periodical_results/data/2019nCoVR_20200301.zip</a></li><li>新冠病毒基因序列，总共1020条，长度层次不齐，未经过有效挑选</li><li><a href="http://lab.malab.cn/~cjt/MSA/data/SARS-CoV-2_20200417.7z" target="_blank" rel="noreferrer">http://lab.malab.cn/~cjt/MSA/data/SARS-CoV-2_20200417.7z</a></li><li>新冠病毒基因序列，总共13w条，相似度较高，长度大于29000bp (序列已对齐，对比前请去除&#39;-&#39;)</li><li><a href="http://lab.malab.cn/~cjt/MSA/data/msa_1012.tar-2.xz" target="_blank" rel="noreferrer">http://lab.malab.cn/~cjt/MSA/data/msa_1012.tar-2.xz</a></li><li>新冠病毒基因序列，总共1M条，相似度较高，长度大于29000bp (序列已对齐，对比前请去除&#39;-&#39;)</li><li><a href="http://lab.malab.cn/~tfr/HAlign3_testdata/sars_cov_2_1Mseq.tar.xz" target="_blank" rel="noreferrer">http://lab.malab.cn/~tfr/HAlign3_testdata/sars_cov_2_1Mseq.tar.xz</a></li><li>新冠病毒基因序列，总共24310条，相似度较高，长度大于29000bp</li><li><a href="http://lab.malab.cn/~cjt/MSA/data/SARS-CoV-2.7z" target="_blank" rel="noreferrer">http://lab.malab.cn/~cjt/MSA/data/SARS-CoV-2.7z</a></li><li>新冠病毒基因序列，总共15900933条，长度层次不齐，长度大于29000bp (序列已对齐，对比前请去除&#39;-&#39;)</li><li><a href="http://lab.malab.cn/soft/halign/data/hCoV-19_msa_20230822.tar.xz" target="_blank" rel="noreferrer">http://lab.malab.cn/soft/halign/data/hCoV-19_msa_20230822.tar.xz</a></li></ul><h3 id="猴痘数据集" tabindex="-1">猴痘数据集 <a class="header-anchor" href="#猴痘数据集" aria-label="Permalink to &quot;猴痘数据集&quot;">​</a></h3><ul><li>完整数据集（即完整测序的数据集 MPoxBR.complete.fasta.xz）相似度较高，有 1739 条序列，没有对齐，fasta 格式的 DNA 数据集，长度在 183230~210919 之间，平均长度 197135</li><li>部分数据集（即部分测序的数据集 PoxBR.incomplete.fasta.xz）相似度较低，有 4631 条序列，没有对齐，fasta 格式的 DNA 数据集，长度在 17~228869 之间，平均长度 177921</li><li>最后更新日期：2023-08-19</li><li><a href="https://github.com/malabz/MPoxVR_dataset" target="_blank" rel="noreferrer">Dataset Mainpage</a></li><li><a href="https://github.com/malabz/MPoxVR_dataset/releases/tag/20230819" target="_blank" rel="noreferrer">Dataset Link</a></li></ul><h3 id="iav数据集" tabindex="-1">IAV数据集 <a class="header-anchor" href="#iav数据集" aria-label="Permalink to &quot;IAV数据集&quot;">​</a></h3><ul><li>该数据集包含甲型流感病毒多个基因片段的序列数据，覆盖HA-H1、HA-H3、HA-H5、HA-H7，NA-N1、NA-N2、NA-N9，以及MP、NP、NS、PA、PB1、PB2等片段。IAV基因组由8个负链单股RNA片段组成，不同毒株之间具有较高的遗传多样性，并可通过HA和NA的组合划分为不同亚型。本数据集为每个亚型或基因片段提供对应的参考序列，并进一步构建不同长度的子数据集，适合用于病毒序列分类、亚型识别、片段识别、序列比对和模型输入长度分析等任务。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/iav_data.7z" target="_blank" rel="noreferrer">iav_data.7z</a></li></ul><h3 id="dengue数据集" tabindex="-1">Dengue数据集 <a class="header-anchor" href="#dengue数据集" aria-label="Permalink to &quot;Dengue数据集&quot;">​</a></h3><ul><li>Dengue病毒数据集包含登革病毒基因组序列和参考序列，属于正链单股RNA病毒，存在1–4型血清型，序列间差异较明显，完整基因组长度约10.6–10.7kb，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/dengue.7z" target="_blank" rel="noreferrer">dengue.7z</a></li></ul><h3 id="ebola数据集" tabindex="-1">Ebola数据集 <a class="header-anchor" href="#ebola数据集" aria-label="Permalink to &quot;Ebola数据集&quot;">​</a></h3><ul><li>Ebola病毒数据集包含埃博拉病毒基因组序列和参考序列，属于负链单股RNA病毒，不同种/株之间存在一定变异，完整基因组长度约18.9–19.0kb，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/ebola.7z" target="_blank" rel="noreferrer">ebola.7z</a></li></ul><h3 id="hbv数据集" tabindex="-1">HBV数据集 <a class="header-anchor" href="#hbv数据集" aria-label="Permalink to &quot;HBV数据集&quot;">​</a></h3><ul><li>HBV病毒数据集包含乙型肝炎病毒基因组序列和参考序列，属于部分双链环状DNA病毒，基因组较短但不同基因型之间存在差异，完整基因组长度约3.2kb，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/hbv.7z" target="_blank" rel="noreferrer">hbv.7z</a></li></ul><h3 id="hcv数据集" tabindex="-1">HCV数据集 <a class="header-anchor" href="#hcv数据集" aria-label="Permalink to &quot;HCV数据集&quot;">​</a></h3><ul><li>HCV病毒数据集包含丙型肝炎病毒基因组序列和参考序列，属于正链单股RNA病毒，基因型多、变异程度较高，完整基因组长度约9.4–9.7kb，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/hcv.7z" target="_blank" rel="noreferrer">hcv.7z</a></li></ul><h3 id="hiv-1数据集" tabindex="-1">HIV-1数据集 <a class="header-anchor" href="#hiv-1数据集" aria-label="Permalink to &quot;HIV-1数据集&quot;">​</a></h3><ul><li>HIV-1病毒数据集包含人类免疫缺陷病毒1型基因组序列和参考序列，属于逆转录病毒，序列变异性高，完整RNA基因组长度约9.2–9.8kb，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/hiv-1.7z" target="_blank" rel="noreferrer">hiv-1.7z</a></li></ul><h3 id="measles数据集" tabindex="-1">Measles数据集 <a class="header-anchor" href="#measles数据集" aria-label="Permalink to &quot;Measles数据集&quot;">​</a></h3><ul><li>Measles病毒数据集包含麻疹病毒基因组序列和参考序列，属于负链单股RNA病毒，基因组长度较保守，完整基因组通常为15894bp，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/measles.7z" target="_blank" rel="noreferrer">measles.7z</a></li></ul><h3 id="west-nile数据集" tabindex="-1">West Nile数据集 <a class="header-anchor" href="#west-nile数据集" aria-label="Permalink to &quot;West Nile数据集&quot;">​</a></h3><ul><li>West Nile病毒数据集包含西尼罗病毒基因组序列和参考序列，属于正链单股RNA黄病毒，常用于虫媒病毒分类或进化分析，完整基因组长度约11.0kb，该数据集未经过去重和筛选。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/measles.7z" target="_blank" rel="noreferrer">measles.7z</a></li></ul><h3 id="zika数据集" tabindex="-1">Zika数据集 <a class="header-anchor" href="#zika数据集" aria-label="Permalink to &quot;Zika数据集&quot;">​</a></h3><ul><li>Zika病毒数据集包含寨卡病毒基因组序列和参考序列，属于正链单股RNA黄病毒，与登革病毒和西尼罗病毒同属黄病毒相关类群，完整基因组长度约 10.8 kb。</li><li>Download: <a href="http://lab.malab.cn/soft/msa_test_data/virus/zika.7z" target="_blank" rel="noreferrer">zika.7z</a></li></ul><h2 id="dna-rna模拟数据集" tabindex="-1">DNA/RNA模拟数据集 <a class="header-anchor" href="#dna-rna模拟数据集" aria-label="Permalink to &quot;DNA/RNA模拟数据集&quot;">​</a></h2><h3 id="hierarchical-tree-simulated-datasets" tabindex="-1">Hierarchical tree simulated datasets <a class="header-anchor" href="#hierarchical-tree-simulated-datasets" aria-label="Permalink to &quot;Hierarchical tree simulated datasets&quot;">​</a></h3><ul><li>Ref: <a href="https://doi.org/10.1093/molbev/msac166" target="_blank" rel="noreferrer">HAlign 3</a>: Fast Multiple Alignment of Ultra-Large Numbers of Similar DNA/RNA Sequences.</li><li>Download: <a href="http://lab.malab.cn/~tfr/HAlign3_testdata/sars_cov_2_like_diff_similarity.tar.xz" target="_blank" rel="noreferrer">sars_cov_2_like_diff_similarity.tar.xz</a>, <a href="http://lab.malab.cn/~tfr/HAlign3_testdata/sars_cov_2_like_diff_treelength.tar.xz" target="_blank" rel="noreferrer">sars_cov_2_like_diff_treelength.tar.xz</a>, <a href="http://lab.malab.cn/~tfr/HAlign3_testdata/mt_like_diff_similarity.tar.xz" target="_blank" rel="noreferrer">mt_like_diff_similarity.tar.xz</a>, <a href="http://lab.malab.cn/~tfr/HAlign3_testdata/mt_like_diff_treelength.tar.xz" target="_blank" rel="noreferrer">mt_like_diff_treelength.tar.xz</a></li><li><a href="./simulation.html">使用IQTree和INDELible生成方法</a></li></ul><h3 id="star-tree-simulated-datasets" tabindex="-1">Star-tree simulated datasets <a class="header-anchor" href="#star-tree-simulated-datasets" aria-label="Permalink to &quot;Star-tree simulated datasets&quot;">​</a></h3><ul><li>14 simulated datasets, each dataset contained 1000 sequences in each dataset with different similarities (99%, 98%, 97%, 96%, 95%, 94%, 93%, 92%, 91%, 90%, 85%, 80%, 70%, and 60%).</li><li>Ref: <a href="https://doi.org/10.1093/molbev/msac166" target="_blank" rel="noreferrer">HAlign 3</a>: Fast Multiple Alignment of Ultra-Large Numbers of Similar DNA/RNA Sequences.</li><li>Download: <a href="http://lab.malab.cn/%7Etfr/HAlign3_testdata/star_simudata_1000seq.tar.xz" target="_blank" rel="noreferrer">star_simudata_1000seq.tar.xz</a></li></ul><h3 id="rna模拟数据" tabindex="-1">RNA模拟数据 <a class="header-anchor" href="#rna模拟数据" aria-label="Permalink to &quot;RNA模拟数据&quot;">​</a></h3><ul><li>含二级结构，NEXUS格式，相似度很高</li><li><a href="https://kim.bio.upenn.edu/software/csd.shtml" target="_blank" rel="noreferrer">https://kim.bio.upenn.edu/software/csd.shtml</a></li><li>下载 (zipped file): <a href="http://lab.malab.cn/soft/WMSA2/data/RNA-255.zip" target="_blank" rel="noreferrer">RNA-255</a> <a href="http://lab.malab.cn/soft/WMSA2/data/RNA-511.zip" target="_blank" rel="noreferrer">RNA-511</a> <a href="http://lab.malab.cn/soft/WMSA2/data/RNA-1023.zip" target="_blank" rel="noreferrer">RNA-1023</a> <a href="http://lab.malab.cn/soft/WMSA2/data/RNA-2047.zip" target="_blank" rel="noreferrer">RNA-2047</a> <a href="http://lab.malab.cn/soft/WMSA2/data/RNA-4095.zip" target="_blank" rel="noreferrer">RNA-4095</a> <a href="http://lab.malab.cn/soft/WMSA2/data/RNA-8191.zip" target="_blank" rel="noreferrer">RNA-8191</a></li></ul><h3 id="模拟noncoding数据" tabindex="-1">模拟noncoding数据 <a class="header-anchor" href="#模拟noncoding数据" aria-label="Permalink to &quot;模拟noncoding数据&quot;">​</a></h3><ul><li>相似度较低，有较多类型的数据，fasta格式</li><li><a href="http://bioinfolab.unl.edu/~cstrope/iSG/benchmark/index.html" target="_blank" rel="noreferrer">http://bioinfolab.unl.edu/~cstrope/iSG/benchmark/index.html</a></li></ul><h2 id="蛋白质数据集" tabindex="-1">蛋白质数据集 <a class="header-anchor" href="#蛋白质数据集" aria-label="Permalink to &quot;蛋白质数据集&quot;">​</a></h2><h3 id="muscle-数据集" tabindex="-1">MUSCLE 数据集 <a class="header-anchor" href="#muscle-数据集" aria-label="Permalink to &quot;MUSCLE 数据集&quot;">​</a></h3><ul><li>相似度较低，有较多类型的数据，fasta格式，以蛋白质数据集为主</li><li><a href="http://www.drive5.com/bench/" target="_blank" rel="noreferrer">http://www.drive5.com/bench/</a></li><li><a href="https://github.com/rcedgar/balifam" target="_blank" rel="noreferrer">https://github.com/rcedgar/balifam</a></li><li><a href="https://github.com/rcedgar/qscore" target="_blank" rel="noreferrer">Q Score 程序</a></li></ul><h3 id="exthomfam-数据集" tabindex="-1">extHomFam 数据集 <a class="header-anchor" href="#exthomfam-数据集" aria-label="Permalink to &quot;extHomFam 数据集&quot;">​</a></h3><ul><li>相似度较低，序列长度短(&lt;100bp)，文件内序列数量多(最多415519条)，有金标准对齐，fasta格式，蛋白质数据集</li><li>金标准对比结果同样采用 <a href="https://github.com/rcedgar/qscore" target="_blank" rel="noreferrer">Q Score 程序</a></li><li><a href="https://dataverse.harvard.edu/dataset.xhtml?persistentId=doi:10.7910/DVN/BO2SVW" target="_blank" rel="noreferrer">Dataset Link</a></li></ul><h3 id="quantest2-数据集" tabindex="-1">QuanTest2 数据集 <a class="header-anchor" href="#quantest2-数据集" aria-label="Permalink to &quot;QuanTest2 数据集&quot;">​</a></h3><ul><li>蛋白质数据集，相似度较低</li><li>Ref: Sievers, F. et al. (2020) QuanTest2: benchmarking multiple sequence alignments using secondary structure prediction, Bioinformatics, 36(1), January 2020, 90–95.</li><li>原版利用二级结构进行预测，<a href="http://bioinf.ucd.ie/quantest2.tar" target="_blank" rel="noreferrer">下载地址</a></li><li>利用 Q Score 和 TC Score 进行得分计算，<a href="https://github.com/malabz/QuanTest2" target="_blank" rel="noreferrer">Dataset Mainpage</a></li></ul><h3 id="pfam-38-1-full子数据集" tabindex="-1">Pfam(38.1) full子数据集 <a class="header-anchor" href="#pfam-38-1-full子数据集" aria-label="Permalink to &quot;Pfam(38.1) full子数据集&quot;">​</a></h3><ul><li>基于Pfam full alignment 构建的真实蛋白质家族子集，从多个Pfam家族中抽取部分成员形成测试数据。Pfam家族以多序列比对和profile HMM表示，full alignment包含更大范围的同源成员，适合构建真实场景下的MSA测试集。</li><li>蛋白质数据集，覆盖不同家族规模、序列长度和相似度水平，可用于测试比对方法在低相似、高冗余、规模变化等条件下的表现。</li><li>与BAliBASE等结构参考基准不同，该数据集强调真实家族覆盖与规模多样性，适合用于算法性能评测、参数敏感性分析以及大规模比对实验；若需参考型质量评估，可结合Pfam seed alignment或其他高可信参考集进行比较。Pfam的seed是经整理的核心对齐，full则是在profile HMM搜索基础上扩展得到的更大成员集合。</li><li>下载: <a href="http://lab.malab.cn/soft/msa_test_data/protein/pfam_subset.7z" target="_blank" rel="noreferrer">pfam_subset.7z</a></li></ul><h3 id="iq-tree3模拟数据集" tabindex="-1">IQ-TREE3模拟数据集 <a class="header-anchor" href="#iq-tree3模拟数据集" aria-label="Permalink to &quot;IQ-TREE3模拟数据集&quot;">​</a></h3><ul><li>基于IQ-TREE3的AliSim模拟器构建，通过控制序列长度、叶子节点数、进化距离和替换模型等参数，生成不同难度与不同规模的模拟多序列比对数据。</li><li>数据集覆盖从低分化到高分化、从小规模到大规模、从短序列到长序列的多种场景，适合测试多序列比对算法在复杂进化条件下的准确性、稳定性与可扩展性。</li><li>下载: <a href="http://lab.malab.cn/soft/msa_test_data/protein/iqtree_simulated.7z" target="_blank" rel="noreferrer">iqtree_simulated.7z</a></li></ul>',73)])])}const f=e(i,[["render",n]]);export{d as __pageData,f as default};
